import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ user, onSelectConversation }) => {
  const [conversations, setConversations] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState([]);

  useEffect(() => {
    if (!user) return;

    const fetchConversations = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/conversations/${user.userId}`);
        setConversations(res.data);
      } catch (err) {
        console.error("Error fetching conversations:", err);
      }
    };

    fetchConversations();
  }, [user]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    try {
      const res = await axios.get(`http://localhost:5000/api/profile/search?username=${searchQuery}`);
      setSearchResults(res.data);
    } catch (err) {
      console.error("Error searching users:", err);
    }
  };

  const handleStartConversation = async (receiver) => {
    try {
      const res = await axios.post("http://localhost:5000/api/conversations", {
        senderId: user.userId,
        receiverId: receiver._id,
        senderUsername: user.username,
        receiverUsername: receiver.username,
      });
      onSelectConversation(res.data);
    } catch (err) {
      console.error("Error starting conversation:", err);
    }
  };

  return (
    <div className="chat-sidebar">
      <h3>Messages</h3>
      <input
        type="text"
        placeholder="Search by username"
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
        onKeyPress={(e) => e.key === "Enter" && handleSearch()}
      />
      <button onClick={handleSearch}>Search</button>

      {searchResults.length > 0 && (
        <ul className="search-results">
          {searchResults.map((user) => (
            <li key={user._id} onClick={() => handleStartConversation(user)}>
              {user.username}
            </li>
          ))}
        </ul>
      )}

      {conversations.length === 0 ? (
        <p>No conversations found.</p>
      ) : (
        <ul className="conversation-list">
          {conversations.map((c) => (
            <li key={c._id} onClick={() => onSelectConversation(c)}>
              <strong>{c.participantUsernames.find(name => name !== user.username)}</strong>
              <br />
              <span>{c.lastMessage}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default ChatSidebar;
